"""Tests use generated bytes and local bare Git; no remote network or training."""
import json
import os
from pathlib import Path
import shutil
import tempfile
import unittest
import checkpoint_parts as cp


class PartsTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name)
        self.source = self.root / 'model.safetensors'
        self.source.write_bytes(bytes(range(251)) * 33)
        self.folder = self.root / 'parts'
        self.manifest = cp.split(self.source, self.folder, 1000, 'synthetic-test')

    def tearDown(self):
        self.tmp.cleanup()

    def edit(self, fn):
        manifest = json.loads((self.folder / 'MANIFEST.json').read_text())
        fn(manifest)
        (self.folder / 'MANIFEST.json').write_text(json.dumps(manifest))

    def test_roundtrip(self):
        output = self.root / 'restore' / 'model.safetensors'
        cp.restore(self.folder, output)
        self.assertEqual(self.source.read_bytes(), output.read_bytes())
        self.assertEqual(cp.digest(output), self.manifest['sha256'])

    def test_exact_boundary(self):
        p = self.root / 'exact'; p.write_bytes(b'a' * 2000)
        m = cp.split(p, self.root / 'exact-parts', 1000)
        self.assertEqual([x['size_bytes'] for x in m['parts']], [1000, 1000])

    def test_limit_rejected(self):
        for size in (0, -1, 90_000_000, 100_000_000):
            with self.subTest(size=size), self.assertRaises(ValueError):
                cp.split(self.source, self.root / 'invalid', size)

    def test_empty_rejected(self):
        p = self.root / 'empty'; p.touch()
        with self.assertRaises(ValueError): cp.split(p, self.root / 'empty-parts')

    def test_missing_source(self):
        with self.assertRaises(ValueError): cp.split(self.root / 'absent', self.root / 'missing-parts')

    def test_wrong_source_hash(self):
        p = self.root / 'bad-hash'
        with self.assertRaises(ValueError): cp.split(self.source, p, expected_sha256='0' * 64)
        self.assertFalse(p.exists())

    def test_no_split_overwrite(self):
        with self.assertRaises(FileExistsError): cp.split(self.source, self.folder)
        cp.verify(self.folder)

    def test_no_restore_overwrite(self):
        with self.assertRaises(FileExistsError): cp.restore(self.folder, self.source)
        self.assertEqual(cp.digest(self.source), self.manifest['sha256'])

    def test_corrupt_bytes_cleanup(self):
        p = self.folder / self.manifest['parts'][0]['name']
        data = bytearray(p.read_bytes()); data[1] ^= 255; p.write_bytes(data)
        output = self.root / 'bad-output'
        with self.assertRaises(ValueError): cp.restore(self.folder, output)
        self.assertFalse(output.exists())
        self.assertFalse(list(self.root.glob('.restore-*')))

    def test_missing_part(self):
        (self.folder / self.manifest['parts'][0]['name']).unlink()
        with self.assertRaises(ValueError): cp.verify(self.folder)

    def test_truncated_part(self):
        (self.folder / self.manifest['parts'][0]['name']).write_bytes(b'x')
        with self.assertRaises(ValueError): cp.verify(self.folder)

    def test_reordered_parts(self):
        self.edit(lambda m: m['parts'].reverse())
        with self.assertRaises(ValueError): cp.verify(self.folder)

    def test_duplicate_part(self):
        self.edit(lambda m: m['parts'].__setitem__(1, dict(m['parts'][0])))
        with self.assertRaises(ValueError): cp.verify(self.folder)

    def test_traversal(self):
        for name in ('../model', '/model', 'C:\\model', 'x/y', 'x\\y'):
            with self.subTest(name=name), self.assertRaises(ValueError): cp.safe_name(name)

    def test_symlink_part(self):
        p = self.folder / self.manifest['parts'][0]['name']; p.unlink()
        p.symlink_to(self.source)
        with self.assertRaises(ValueError): cp.verify(self.folder)

    def test_final_hash(self):
        self.edit(lambda m: m.update(sha256='0' * 64))
        with self.assertRaises(ValueError): cp.verify(self.folder)

    def test_manifest_type(self):
        (self.folder / 'MANIFEST.json').write_text('[]')
        with self.assertRaises(ValueError): cp.verify(self.folder)

    def test_manifest_size(self):
        self.edit(lambda m: m.update(size_bytes=m['size_bytes'] + 1))
        with self.assertRaises(ValueError): cp.verify(self.folder)

    def test_local_git_publication_with_manifest_only_destination(self):
        bare = self.root / 'remote.git'; cp.git('init', '--bare', str(bare))
        working = self.root / 'seed'; cp.git('init', '-b', 'main', str(working))
        target = working / 'models' / 'test'; target.mkdir(parents=True)
        shutil.copyfile(self.folder / 'MANIFEST.json', target / 'MANIFEST.json')
        (working / 'KEEP.txt').write_text('Preserve unrelated work\n')
        (working / '.gitattributes').write_text('*.part* filter=lfs diff=lfs merge=lfs -text\n')
        cp.git('add', '.', cwd=working)
        cp.git('-c', 'user.name=Test', '-c', 'user.email=test@example.invalid', 'commit', '-m', 'seed', cwd=working)
        cp.git('remote', 'add', 'origin', str(bare), cwd=working)
        cp.git('push', 'origin', 'main', cwd=working)
        result = cp.publish(self.folder, str(bare), 'main', 'models/test', 'Test', 'test@example.invalid')
        self.assertEqual(result['sha256'], self.manifest['sha256'])
        self.assertEqual(result['status'], 'remote_bytes_verified')
        repeat = cp.publish(self.folder, str(bare), 'main', 'models/test', 'Test', 'test@example.invalid')
        self.assertEqual(result['commit'], repeat['commit'])
        self.assertEqual(cp.git('--git-dir', str(bare), 'show', 'main:KEEP.txt'), 'Preserve unrelated work')
        # The Git blob contains raw binary, not an LFS pointer.
        self.assertEqual(int(cp.git('--git-dir', str(bare), 'cat-file', '-s', 'main:models/test/' + self.manifest['parts'][0]['name'])), 1000)

if __name__ == '__main__':
    unittest.main(verbosity=2)
